// Extract optional date range from the user message.
// e.g. "show me data from 2026-01-01 to 2026-03-31"
// Falls back to last 90 days if no dates found.
const chatInput = $input.first().json.chatInput || '';

const dates = chatInput.match(/(\d{4}-\d{2}-\d{2})/g) || [];
const today = new Date();
const ago90 = new Date(today);
ago90.setDate(today.getDate() - 90);

return [{
  json: {
    chatInput,
    dateRangeStart: dates[0] || ago90.toISOString().split('T')[0],
    dateRangeEnd:   dates[1] || today.toISOString().split('T')[0]
  }
}];

const daily      = $('Supabase - Daily Aggregates').all().map(i => i.json);
const planBreak  = $('Supabase - Plan & Method Breakdown').all().map(i => i.json);
const trends     = $('Supabase - Monthly Trends').all().map(i => i.json);
const byCountry  = $('Supabase - Customer Revenue by Country').all().map(i => i.json);
const parsed     = $('Parse Chat Input').first().json;

// Linear regression on monthly completed revenue
function linearRegression(rows) {
  const n = rows.length;
  if (n < 2) return { slope: 0, intercept: parseFloat(rows[0]?.completed_amount || rows[0]?.monthly_total || 0), r2: 0 };
  const y = rows.map(r => parseFloat(r.completed_amount || r.monthly_total) || 0);
  const x = y.map((_, i) => i);
  const xm = x.reduce((a, b) => a + b, 0) / n;
  const ym = y.reduce((a, b) => a + b, 0) / n;
  const num = x.reduce((s, xi, i) => s + (xi - xm) * (y[i] - ym), 0);
  const den = x.reduce((s, xi) => s + (xi - xm) ** 2, 0);
  const slope = den ? num / den : 0;
  const intercept = ym - slope * xm;
  const ssRes = y.reduce((s, yi, i) => s + (yi - (slope * i + intercept)) ** 2, 0);
  const ssTot = y.reduce((s, yi) => s + (yi - ym) ** 2, 0);
  return {
    slope:     Math.round(slope * 100) / 100,
    intercept: Math.round(intercept * 100) / 100,
    r2:        ssTot ? Math.round((1 - ssRes / ssTot) * 1000) / 1000 : 1
  };
}

const reg = linearRegression(trends);
const predict = n => Math.round((reg.slope * n + reg.intercept) * 100) / 100;

// Totals
const completedRows = daily.filter(r => r.payment_status === 'completed');
const pendingRows   = daily.filter(r => r.payment_status === 'pending');
const failedRows    = daily.filter(r => r.payment_status === 'failed');
const sum = rows => Math.round(rows.reduce((s, r) => s + parseFloat(r.total_amount || 0), 0) * 100) / 100;

const totalRevenue   = sum(completedRows);
const totalPending   = sum(pendingRows);
const totalFailed    = sum(failedRows);
const totalAll       = sum(daily);
const failureRate    = totalAll > 0 ? Math.round((totalFailed / totalAll) * 10000) / 100 : 0;

// Top plan by revenue
const byPlan = {};
planBreak.filter(r => r.payment_status === 'completed').forEach(r => {
  byPlan[r.plan] = (byPlan[r.plan] || 0) + parseFloat(r.total_amount || 0);
});
const topPlan = Object.entries(byPlan).sort((a, b) => b[1] - a[1])[0];

// Top country by revenue
const topCountry = byCountry[0];

// MoM trend
const last = trends[trends.length - 1];
const trendDir = (last?.mom_pct_change ?? 0) > 0 ? 'upward'
               : (last?.mom_pct_change ?? 0) < 0 ? 'downward' : 'stable';

// Anomaly: plans with failed rate > 20%
const planFailures = {};
const planTotals   = {};
planBreak.forEach(r => {
  const key = r.plan || 'unknown';
  planTotals[key] = (planTotals[key] || 0) + parseInt(r.transaction_count || 0);
  if (r.payment_status === 'failed') {
    planFailures[key] = (planFailures[key] || 0) + parseInt(r.transaction_count || 0);
  }
});
const planAnomalies = Object.entries(planTotals)
  .map(([plan, total]) => ({
    plan,
    failureRate: Math.round(((planFailures[plan] || 0) / total) * 10000) / 100
  }))
  .filter(p => p.failureRate > 20);

return [{
  json: {
    chatInput:      parsed.chatInput,
    dateRangeStart: parsed.dateRangeStart,
    dateRangeEnd:   parsed.dateRangeEnd,
    daily,
    planBreakdown:  planBreak,
    trends,
    byCountry,
    analysis: {
      totalRevenue,
      totalPending,
      totalFailed,
      totalAll,
      failureRate,
      topPlan:        topPlan ? { plan: topPlan[0], revenue: Math.round(topPlan[1] * 100) / 100 } : null,
      topCountry:     topCountry ? { country: topCountry.country, revenue: parseFloat(topCountry.total_revenue) } : null,
      trendDirection: trendDir,
      latestMoMGrowth: parseFloat(last?.mom_pct_change || 0),
      planAnomalies,
      regression: reg,
      predictions: {
        nextMonth:    predict(trends.length),
        twoMonthsOut: predict(trends.length + 1)
      }
    }
  }
}];

