const reportContent = $input.first().json.message.content;
const ctx           = $('Compute Analysis & Predictions').first().json;
const reportId      = 'RPT-' + Date.now();

return [{
  json: {
    reportId,
    generatedAt:    new Date().toISOString(),
    chatInput:      ctx.chatInput,
    dateRangeStart: ctx.dateRangeStart,
    dateRangeEnd:   ctx.dateRangeEnd,
    reportContent,
    analysisSummary: ctx.analysis
  }
}];

// Return the Markdown report as the chat reply.
return [{
  json: {
    output: $('Format Report Output').first().json.reportContent
  }
}];
